mapper.select:
SELECT COUNT(*)
FROM member_profile
WHERE mem_nickname = #{mem_nickname}

mapper.update:
UPDATE member_profile
SET mem_img = #{mem_img, jdbcType=VARCHAR}
WHERE mem_idx = #{mem_idx}

UPDATE member_addr
SET mem_addr = #{mem_addr}
WHERE mem_idx = #{mem_idx}

UPDATE member_addr
SET
    mem_zipcode = #{mem_zipcode},
    mem_addr = #{mem_addr},
    mem_addr_detail = #{mem_addr_detail}
WHERE mem_idx = #{mem_idx}
